<?php
require __DIR__ . '/includes/auth.php'; require_staff(); require __DIR__ . '/config/database.php'; require __DIR__ . '/config/collection_schedule.php';
$saved = false; $collected = false; $error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (($_POST['action'] ?? '') === 'collect') {
        $request_id = (int)($_POST['request_id'] ?? 0);
        if ($request_id > 0) {
            $stmt = $pdo->prepare('UPDATE stationery_requests SET status=?, collected_at=NOW() WHERE id=? AND status=? AND (requester_id=? OR (requester_id IS NULL AND requester_name=?))');
            $stmt->execute(['collected', $request_id, 'approved', $_SESSION['user_id'], $_SESSION['user_name']]);
            $collected = $stmt->rowCount() > 0;
            if (!$collected) $error = 'This request cannot be marked as collected.';
        }
    } else {
        $item = trim($_POST['item_name'] ?? ''); $quantity = (int)($_POST['quantity'] ?? 0);
        if ($item === '' || $quantity < 1) $error = 'Enter the stationery name and a quantity of at least 1.';
        else {
            $stmt = $pdo->prepare('INSERT INTO stationery_requests (requester_id,requester_name,item_name,category,quantity,reason) VALUES (?,?,?,?,?,?)');
            $stmt->execute([$_SESSION['user_id'], $_SESSION['user_name'], $item, $_POST['category'] ?? 'Other', $quantity, trim($_POST['reason'] ?? '')]);
            $saved = true;
        }
    }
}
$stmt = $pdo->prepare('SELECT id,item_name,quantity,status,created_at,collected_at FROM stationery_requests WHERE requester_id=? OR (requester_id IS NULL AND requester_name=?) ORDER BY id DESC LIMIT 8');
$stmt->execute([$_SESSION['user_id'], $_SESSION['user_name']]); $requests = $stmt->fetchAll();
$notes = $pdo->prepare('SELECT title,message,created_at FROM notifications WHERE user_id=? ORDER BY id DESC LIMIT 5');
$notes->execute([$_SESSION['user_id']]); $notes = $notes->fetchAll();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SIMS | Request Stationery</title><link rel="stylesheet" href="assets/css/style.css"><style>.request-layout{display:grid;grid-template-columns:1fr .9fr;gap:20px;margin-top:25px}.request-layout label{display:block;font-size:12px;font-weight:700;margin:15px 0}.request-layout input,.request-layout select{display:block;width:100%;border:1px solid #e8e8f0;border-radius:7px;padding:11px;margin-top:7px;font:inherit}.notice-card{background:#edfcf6;border-left:4px solid #21a97d;padding:14px;border-radius:7px;color:#16684f;font-size:13px;line-height:1.55}.request-ok{background:#dcfce7;color:#15803d;padding:12px;border-radius:8px;font-size:13px}.request-table h2,.notifications h2{font-size:17px;margin-top:0}.approved{background:#dcfce7;color:#15803d}.collected{background:#dbeafe;color:#1d4ed8}.rejected{background:#ffe4e6;color:#be123c}.notification{border-bottom:1px solid #e8e8f0;padding:11px 0}.notification:last-child{border:0}.notification strong{display:block;font-size:13px}.notification small{color:#6b7280}@media(max-width:800px){.request-layout{grid-template-columns:1fr}}</style></head><body class="dashboard-page"><aside class="sidebar"><div class="logo"><span>✎</span><div><strong>SIMS</strong><small>Stationery Inventory</small></div></div><nav><a href="dashboard.php">▦ Dashboard</a><a class="active" href="request_stationery.php">✉ Request stationery</a></nav><a class="logout" href="logout.php">⇥ Sign out</a></aside><main class="dashboard"><header><div><p class="eyebrow">STAFF PORTAL › REQUEST STATIONERY</p><h1>Request Stationery</h1><p class="muted">Send your request. Approved stationery is collected at the ICT Counter.</p></div></header><?php if($saved):?><p class="request-ok">Request sent. You will receive a collection notification after Admin approval.</p><?php endif;?><?php if($collected):?><p class="request-ok">Request marked as collected successfully.</p><?php endif;?><?php if($error):?><p class="alert"><?=htmlspecialchars($error)?></p><?php endif;?><div class="request-layout"><form class="content-card" method="post"><h2>New Request</h2><label>Stationery name *<input name="item_name" required placeholder="Example: Black ballpoint pen"></label><label>Category *<select name="category"><option>Writing</option><option>Paper</option><option>Office tools</option><option>Filing</option><option>Adhesives</option><option>Other</option></select></label><label>Quantity needed *<input name="quantity" type="number" min="1" required></label><label>Reason / purpose<input name="reason" placeholder="Example: Needed for class registration"></label><button class="primary-btn" type="submit">Send Request</button></form><section><div class="notice-card"><strong>Collection schedule</strong><br>Approved stationery can be collected at the <strong><?=COLLECTION_LOCATION?></strong> on <strong><?=COLLECTION_DAY?></strong>, <?=COLLECTION_TIME?>.</div><div class="content-card notifications" style="margin-top:18px"><h2>My Notifications</h2><?php if(!$notes):?><p class="muted">No notifications yet.</p><?php else:?><?php foreach($notes as $note):?><div class="notification"><strong><?=htmlspecialchars($note['title'])?></strong><span><?=htmlspecialchars($note['message'])?></span><br><small><?=date('d M Y, h:i A',strtotime($note['created_at']))?></small></div><?php endforeach;?><?php endif;?></div><div class="content-card request-table" style="margin-top:18px"><h2>My Recent Requests</h2><?php if(!$requests):?><p class="muted">You have not sent any requests yet.</p><?php else:?><table><thead><tr><th>Item</th><th>Qty</th><th>Status</th></tr></thead><tbody><?php foreach($requests as $r):?><tr><td><strong><?=htmlspecialchars($r['item_name'])?></strong><br><small><?=date('d M Y',strtotime($r['created_at']))?></small></td><td><?= (int)$r['quantity']?></td><td><span class="badge <?=htmlspecialchars($r['status'])?>"><?=ucfirst(htmlspecialchars($r['status']))?></span><?php if($r['status']==='approved'):?><form method="post" style="margin-top:7px"><input type="hidden" name="action" value="collect"><input type="hidden" name="request_id" value="<?= (int)$r['id']?>"><button class="primary-btn small" type="submit">Mark as Collected</button></form><?php elseif($r['status']==='collected' && !empty($r['collected_at'])):?><br><small>Collected <?=date('d M Y, h:i A',strtotime($r['collected_at']))?></small><?php endif;?></td></tr><?php endforeach;?></tbody></table><?php endif;?></div></section></div></main></body></html>
